	@Test
	void preservesEscapesAndChecksumsAcrossStreamingAndRotation() throws Exception {
		String lexical = "quotes\" slash\\ newline\n tab\t null\0 unicode\u00e9\ud83d\ude00".repeat(8192);
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(tempDir)
				.storeUuid("stream-escape-test")
				.batchBufferBytes(4097)
				.maxSegmentBytes(64 * 1024)
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.COMMIT)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, "before", "", "", 1);
			wal.logMint(2, ValueStoreWalValueKind.LITERAL, lexical, "http://example.com/type", "", 2);
			wal.logMint(3, ValueStoreWalValueKind.LITERAL, "after", "", "", 3);
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			var result = reader.scan();
			assertThat(result.complete()).isTrue();
			assertThat(result.records()).extracting(ValueStoreWalRecord::lexical)
					.containsExactly("before", lexical, "after");
		}
	}

