	public static final class LargeRecordWriter {
		public static void main(String[] args) throws Exception {
			Path directory = Path.of(args[0]);
			if ("buffers".equals(args[1])) {
				ValueStoreWalConfig config = ValueStoreWalConfig.builder()
						.walDirectory(directory)
						.storeUuid("bounded-buffers")
						.queueCapacity(Integer.MAX_VALUE)
						.batchBufferBytes(Integer.MAX_VALUE)
						.syncPolicy(ValueStoreWalConfig.SyncPolicy.COMMIT)
						.build();
				try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
					long lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "small", "", "", 0);
					wal.awaitDurable(lsn);
				}
				if (Files.size(directory.resolve("wal-1.v1")) == 0) {
					throw new AssertionError("WAL record was not written");
				}
				return;
			}
			if ("header".equals(args[1])) {
				readLargeHeader(directory);
				return;
			}
			int length = 24 * 1024 * 1024;
			try (ValueStoreWAL wal = ValueStoreWAL.open(config(directory))) {
				long lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "x".repeat(length), "", "", 0);
				wal.awaitDurable(lsn);
			}
			long count = 0;
			try (var in = new BufferedInputStream(Files.newInputStream(directory.resolve("wal-1.v1")))) {
				byte[] bytes = new byte[8192];
				int read;
				while ((read = in.read(bytes)) >= 0) {
					for (int i = 0; i < read; i++) {
						if (bytes[i] == 'x') {
							count++;
						}
					}
				}
			}
			// The lexical form and the property name "lex" contain all x characters in the JSON payloads.
			// Binary frame lengths/checksums may contribute at most sixteen additional bytes.
			if (count < length + 1 || count > length + 17) {
				throw new AssertionError("WAL lexical content was not fully written: " + count);
			}
		}

		private static void readLargeHeader(Path directory) throws Exception {
			Files.createDirectories(directory);
			Path segment = directory.resolve("wal-1.v1.gz");
			byte[] prefix = "{\"t\":\"V\",\"ignored\":\"".getBytes(StandardCharsets.UTF_8);
			byte[] suffix = "\",\"segment\":1}".getBytes(StandardCharsets.UTF_8);
			int padding = 48 * 1024 * 1024;
			byte[] chunk = new byte[8192];
			Arrays.fill(chunk, (byte) 'x');
			try (var out = new GZIPOutputStream(Files.newOutputStream(segment))) {
				out.write(ByteBuffer.allocate(4)
						.order(ByteOrder.LITTLE_ENDIAN)
						.putInt(prefix.length + padding + suffix.length)
						.array());
				out.write(prefix);
				for (int written = 0; written < padding; written += chunk.length) {
					out.write(chunk);
				}
				out.write(suffix);
				out.write(new byte[4]);
			}
			if (ValueStoreWAL.readSegmentSequence(segment) != 1) {
				throw new AssertionError("Segment sequence was not read");
			}
		}
	}
